import{_ as l,l as o,o as e,c as i,v as t,p as n,x as r,d as s,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"校准与 ECE","description":"","frontmatter":{"title":"校准与 ECE","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/calibration-ece.md","filePath":"llm/calibration-ece.md","lastUpdated":1789023840000}'),c={name:"llm/calibration-ece.md"};function h(m,a,_,C,B,u){const E=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="校准与-ece" tabindex="-1">校准与 ECE <a class="header-anchor" href="#校准与-ece" aria-label="Permalink to &quot;校准与 ECE&quot;">​</a></h1><div class="epigraph"><p>准确率高仍可以系统性过自信。把预测概率装进箱子，看置信与命中率差多少，这才是校准，不是再刷一题准确率。</p><footer>—— Guo 等对现代网络校准的观察；ECE 见 Naeini 等</footer></div><p><a href="/llm/pass-at-k">上一课</a>说明多样本可以「撞到对的」。产品还要问：模型说有八成把握时，是不是大约八成对。本课写校准与期望校准误差（Expected Calibration Error, ECE）。缺口不是再讲 softmax，而是把<strong>置信数字</strong>当成要评测的输出。后课 TruthfulQA 会用到：会说假话的模型往往也过自信。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Guo 等人指出，深度网络在准确率升高的同时 ECE 变差：温度缩放之前，top-1 置信普遍偏高。语言模型同样：选项似然或「口头概率」不是频率。Kadavath 等人问模型「你答得对吗」，发现一定条件下口头置信有信号，但远非已校准。把未校准置信拿去拒答或级联，阈值没有频率含义。</p><p>ECE 把预测按置信分箱，每箱比平均置信与平均准确率，再按箱质量加权求和。箱数、是否自适应分箱、是否只看正确类，都会改 ECE 的值——它是协议，不是唯一的校准本体。</p><p><span class="marginnote">Brier 分数同时惩罚校准与锐度；ECE 更接近「置信刻度准不准」。只报 ECE 可能奖励「永远说 0.5」的钝模型。准确率与校准要同表。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对分类式评测：取预测类的概率 \\(\\hat{p}\\)，分 \\(M\\) 箱，</p> \\[\\mathrm{ECE}=\\sum_{m=1}^{M}\\frac{|B_m|}{n}\\bigl|\\mathrm{acc}(B_m)-\\mathrm{conf}(B_m)\\bigr|. \\]<p>口头概率：用固定提示引出 0–100 的数字，再当 \\(\\hat{p}\\)；这与 token 似然不是同一个随机变量，必须分列。温度缩放在验证集上拟合一个 \\(T\\)，只改置信不改 argmax，可降低 ECE，不提高准确率——不要把它写成能力进步。</p>',11)),(e(),n(p,null,{default:r(()=>[d(E,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20PRED%5B%22%E9%A2%84%E6%B5%8B%E4%B8%8E%E7%BD%AE%E4%BF%A1%22%5D%20--%3E%20BIN%5B%22%E5%88%86%E7%AE%B1%22%5D%0A%20%20BIN%20--%3E%20ACC%5B%22%E7%AE%B1%E5%86%85%E5%87%86%E7%A1%AE%E7%8E%87%22%5D%0A%20%20BIN%20--%3E%20CF%5B%22%E7%AE%B1%E5%86%85%E5%B9%B3%E5%9D%87%E7%BD%AE%E4%BF%A1%22%5D%0A%20%20ACC%20--%3E%20ECE%5B%22%E5%8A%A0%E6%9D%83%E7%BB%9D%E5%AF%B9%E5%B7%AE%22%5D%0A%20%20CF%20--%3E%20ECE%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>过自信来自：训练损失推动概率质量堆到众数、RLHF 奖励「听起来确定」、解码温度低于训练。ECE 看见的是边际频率，看不见条件于题目难度的校准。难的题上自信仍高，是更危险的失准，需要按难度分层报。选择性预测（低于阈值则弃权）把校准变成决策：阈值应按验证集上的风险来，而不是按 0.8 的整数魅力。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>生成式开放答案没有单一 \\(\\hat{p}\\)。可用自洽投票比例或口头置信当代理，但那是另一套仪器。下一课 TruthfulQA 测的是「是否说人爱听的假话」，与 ECE 相关但不是同一声明。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ECE 测置信与频率的箱级偏差，必须与准确率同表。</li><li>token 似然与口头概率分列；温度缩放只校准不增能力。</li><li>按难度分层，避免平均 ECE 掩盖难题上的过自信。</li><li>出处：Naeini 等 ECE；Guo 等 ICML 2017；Kadavath 等口头自信。</li></ul>',6))])}const b=l(c,[["render",h]]);export{f as __pageData,b as default};
